from collections import Counter

def transform(grid, threshold=.80):
    H,W=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # prefix sums each color and non-bg
    colors=set(v for row in grid for v in row if v!=bg)
    pref={}
    for col in colors|{bg}:
        a=[[0]*(W+1) for _ in range(H+1)]
        for r in range(H):
            run=0
            for c in range(W):
                run += grid[r][c]==col
                a[r+1][c+1]=a[r][c+1]+run
        pref[col]=a
    def rectsum(a,r1,c1,r2,c2):return a[r2+1][c2+1]-a[r1][c2+1]-a[r2+1][c1]+a[r1][c1]
    candidates=[]
    for color in colors:
      pc=pref[color]; pb=pref[bg]
      for r1 in range(H-1):
       for r2 in range(r1+1,H):
        h=r2-r1+1
        for c1 in range(W-1):
         for c2 in range(c1+1,W):
          area=h*(c2-c1+1)
          if area<4: continue
          if rectsum(pb,r1,c1,r2,c2): continue
          n=rectsum(pc,r1,c1,r2,c2)
          if n/area>=threshold:
           candidates.append((area,n/area,n,color,r1,c1,r2,c2))
    candidates.sort(reverse=True)
    chosen=[]; occ=[[False]*W for _ in range(H)]
    for cand in candidates:
      area,ratio,n,color,r1,c1,r2,c2=cand
      if any(occ[r][c] for r in range(r1,r2+1) for c in range(c1,c2+1)):continue
      chosen.append(cand)
      for r in range(r1,r2+1):
       for c in range(c1,c2+1):occ[r][c]=True
    out=[[bg]*W for _ in range(H)]
    for area,ratio,n,color,r1,c1,r2,c2 in chosen:
      for r in range(r1,r2+1):
       for c in range(c1,c2+1):out[r][c]=color
    return out,chosen,bg
