program='''from collections import Counter


def transform(grid):
    """Restore mostly solid rectangular color objects and clear scattered noise."""
    h, w = len(grid), len(grid[0])
    background = Counter(cell for row in grid for cell in row).most_common(1)[0][0]
    colors = {cell for row in grid for cell in row if cell != background}

    # Summed-area tables make testing all possible rectangles inexpensive.
    prefix = {}
    for color in colors | {background}:
        table = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            running = 0
            for c in range(w):
                running += grid[r][c] == color
                table[r + 1][c + 1] = table[r][c + 1] + running
        prefix[color] = table

    def count(table, r1, c1, r2, c2):
        return (table[r2 + 1][c2 + 1] - table[r1][c2 + 1]
                - table[r2 + 1][c1] + table[r1][c1])

    candidates = []
    bg_table = prefix[background]
    for color in colors:
        table = prefix[color]
        for r1 in range(h - 1):
            for r2 in range(r1 + 1, h):
                for c1 in range(w - 1):
                    for c2 in range(c1 + 1, w):
                        area = (r2 - r1 + 1) * (c2 - c1 + 1)
                        # Object rectangles have no background gaps. Other
                        # colors inside them are sparse corruptions.
                        if count(bg_table, r1, c1, r2, c2):
                            continue
                        own = count(table, r1, c1, r2, c2)
                        if own >= 4 and own / area >= 0.70:
                            candidates.append((area, own / area, own, color,
                                              r1, c1, r2, c2))

    # Prefer large, clean rectangles. A rectangle can only be selected once.
    candidates.sort(reverse=True)
    occupied = [[False] * w for _ in range(h)]
    selected = []
    for candidate in candidates:
        area, purity, own, color, r1, c1, r2, c2 = candidate
        if any(occupied[r][c]
               for r in range(r1, r2 + 1)
               for c in range(c1, c2 + 1)):
            continue
        selected.append(candidate)
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                occupied[r][c] = True

    result = [[background] * w for _ in range(h)]
    for _, _, _, color, r1, c1, r2, c2 in selected:
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                result[r][c] = color
    return result
'''
